10. Place in the fridge or freezer to set until ready to eat.$r$ where name=$r$Cookie Dough Bites$r$ and image_url not like $x$%abook-%$x$;
update public.recipes set method=$r$1. Line a small plate or dish with parchment paper and set aside.
